func NewFacetsValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (FacetsValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing FacetsValue Attribute Value",
				"While creating a FacetsValue value, a missing attribute value was detected. "+
					"A FacetsValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("FacetsValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid FacetsValue Attribute Type",
				"While creating a FacetsValue value, an invalid attribute value was detected. "+
					"A FacetsValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("FacetsValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("FacetsValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra FacetsValue Attribute Value",
				"While creating a FacetsValue value, an extra attribute value was detected. "+
					"A FacetsValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra FacetsValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewFacetsValueUnknown(), diags
	}

	categoryAttribute, ok := attributes["category"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`category is missing from object`)

		return NewFacetsValueUnknown(), diags
	}

	categoryVal, ok := categoryAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`category expected to be basetypes.StringValue, was: %T`, categoryAttribute))
	}

	hintAttribute, ok := attributes["hint"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`hint is missing from object`)

		return NewFacetsValueUnknown(), diags
	}

	hintVal, ok := hintAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`hint expected to be basetypes.StringValue, was: %T`, hintAttribute))
	}

	keyAttribute, ok := attributes["key"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`key is missing from object`)

		return NewFacetsValueUnknown(), diags
	}

	keyVal, ok := keyAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`key expected to be basetypes.StringValue, was: %T`, keyAttribute))
	}

	labelAttribute, ok := attributes["label"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`label is missing from object`)

		return NewFacetsValueUnknown(), diags
	}

	labelVal, ok := labelAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`label expected to be basetypes.StringValue, was: %T`, labelAttribute))
	}

	requiredAttribute, ok := attributes["required"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`required is missing from object`)

		return NewFacetsValueUnknown(), diags
	}

	requiredVal, ok := requiredAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`required expected to be basetypes.BoolValue, was: %T`, requiredAttribute))
	}

	if diags.HasError() {
		return NewFacetsValueUnknown(), diags
	}

	return FacetsValue{
		Category: categoryVal,
		Hint:     hintVal,
		Key:      keyVal,
		Label:    labelVal,
		Required: requiredVal,
		state:    attr.ValueStateKnown,
	}, diags
}

func NewFacetsValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) FacetsValue {
	object, diags := NewFacetsValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewFacetsValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t FacetsType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewFacetsValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewFacetsValueUnknown(), nil
	}

	if in.IsNull() {
		return NewFacetsValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewFacetsValueMust(FacetsValue{}.AttributeTypes(ctx), attributes), nil
}

func (t FacetsType) ValueType(ctx context.Context) attr.Value {
	return FacetsValue{}
}

var _ basetypes.ObjectValuable = FacetsValue{}

type FacetsValue struct {
	Category basetypes.StringValue `tfsdk:"category"`
	Hint     basetypes.StringValue `tfsdk:"hint"`
	Key      basetypes.StringValue `tfsdk:"key"`
	Label    basetypes.StringValue `tfsdk:"label"`
	Required basetypes.BoolValue   `tfsdk:"required"`
	state    attr.ValueState
}

func (v FacetsValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 5)

	var val tftypes.Value
	var err error

	attrTypes["category"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["hint"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["key"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["label"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["required"] = basetypes.BoolType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 5)

		val, err = v.Category.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["category"] = val

		val, err = v.Hint.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["hint"] = val

		val, err = v.Key.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["key"] = val

		val, err = v.Label.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["label"] = val

		val, err = v.Required.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["required"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v FacetsValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v FacetsValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v FacetsValue) String() string {
	return "FacetsValue"
}

func (v FacetsValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"category": basetypes.StringType{},
		"hint":     basetypes.StringType{},
		"key":      basetypes.StringType{},
		"label":    basetypes.StringType{},
		"required": basetypes.BoolType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"category": v.Category,
			"hint":     v.Hint,
			"key":      v.Key,
			"label":    v.Label,
			"required": v.Required,
		})

	return objVal, diags
}

func (v FacetsValue) Equal(o attr.Value) bool {
	other, ok := o.(FacetsValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Category.Equal(other.Category) {
		return false
	}

	if !v.Hint.Equal(other.Hint) {
		return false
	}

	if !v.Key.Equal(other.Key) {
		return false
	}

	if !v.Label.Equal(other.Label) {
		return false
	}

	if !v.Required.Equal(other.Required) {
		return false
	}

	return true
}

func (v FacetsValue) Type(ctx context.Context) attr.Type {
	return FacetsType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

func (v FacetsValue) AttributeTypes(ctx context.Context) map[string]attr.Type {
	return map[string]attr.Type{
		"category": basetypes.StringType{},
		"hint":     basetypes.StringType{},
		"key":      basetypes.StringType{},
		"label":    basetypes.StringType{},
		"required": basetypes.BoolType{},
	}
}
